import { readFileSync } from 'node:fs';
import { test, expect } from '@playwright/test';
import { pseudoMessages, type Messages } from '../../src/pseudo';

const read = (path: string) => JSON.parse(readFileSync(path, 'utf8')) as Messages;

// The demo's pseudo locale is generated by `fitlocale pseudo`; it must not drift from en.json.
test('demo en-XA.json is the pseudo version of en.json', () => {
  expect(read('demo/locales/en-XA.json')).toEqual(pseudoMessages(read('demo/locales/en.json')));
});
